mapper.select:
SELECT POS.ISSUE_PARTY_ID as issuePartyId, to_date(#{generateDate,jdbcType=VARCHAR},'yyyy-MM-dd') as posDate, POS.PLAN_ASSET_ID as planAssetId, POS.ASSET_CODE as assetCode, POS.TOTAL_NUM as totalNum, POS.ISSUE_AMT as issueAmt, POS.UNINVEST_CASH as uninvestCash, POS.POS_NUM as posNum, POS.POS_AMT as posAmt, '01' status FROM CHB_BOT_AST_POS POS WHERE to_char(POS.POS_DATE,'yyyy-MM-dd') = #{generateDate,jdbcType=VARCHAR}
and POS.ISCHL = '02'
and not exists (select 1 from CHB_BOT_AST_POS_SUB SUB where SUB.POS_DATE = POS.POS_DATE and SUB.PLAN_ASSET_ID = POS.PLAN_ASSET_ID and SUB.ASSET_CODE = POS.ASSET_CODE and SUB.SEND_STATUS in ('02','03'))

select f_guid() REGIST_SEQNO, POS.ISSUE_PARTY_ID as ISSUE_PARTY_ID, to_date(#{generateDate,jdbcType=VARCHAR},'yyyy-MM-dd') as POS_DATE, NVL(PLANASSET.ASSET_CODE_OLD,PLANASSET.ASSET_CODE) as PLAN_ASSET_ID, NVL(BOTASSET.ASSET_CODE_OLD,BOTASSET.ASSET_CODE) as ASSET_CODE, POS.TOTAL_NUM as TOTAL_NUM, POS.ISSUE_AMT as ISSUE_AMT, POS.UNINVEST_CASH as UNINVEST_CASH, POS.POS_NUM as POS_NUM, POS.POS_AMT as POS_AMT, '01' STATUS, '01' SEND_STATUS, #{chbSubmitDeadline,jdbcType=TIMESTAMP} CHB_SUBMIT_DEADLINE, #{submitDeadline,jdbcType=TIMESTAMP} SUBMIT_DEADLINE, POS.ORG_CODE ORG_CODE, POS.DEPT_CODE DEPT_CODE, 'system' CREATE_USER, sysdate CREATE_TIME, 'system' UPDATE_USER, sysdate UPDATE_TIME, #{statusDate,jdbcType=TIMESTAMP} STATUS_DATE FROM CHB_BOT_AST_POS POS LEFT JOIN CHB_ASSET_INFO PLANASSET ON PLANASSET.ASSET_CODE = POS.PLAN_ASSET_ID LEFT JOIN CHB_ASSET_INFO BOTASSET ON BOTASSET.ASSET_CODE = POS.ASSET_CODE WHERE to_char(POS.POS_DATE,'yyyy-MM-dd') = #{generateDate,jdbcType=VARCHAR}
and POS.ISCHL = '02'
and not exists (select 1 from CHB_BOT_AST_POS_SUB SUB where SUB.POS_DATE = POS.POS_DATE and SUB.PLAN_ASSET_ID = POS.PLAN_ASSET_ID and SUB.ASSET_CODE = POS.ASSET_CODE and SUB.SEND_STATUS in ('02','03')) and POS.STATUS != 'D'

mapper.delete:
delete from CHB_BOT_AST_POS_SUB


		to_char(POS_DATE,'yyyy-MM-dd') = #{posDate,jdbcType=VARCHAR}


		and STATUS  = #{status,jdbcType=VARCHAR}


		and SEND_STATUS  = #{sendStatus,jdbcType=VARCHAR}
